// Cloud Translation devuelve el texto como HTML: las comillas y los apóstrofos llegan como &quot; o &#39;.
// Acá se pasan a caracteres normales.
const ENTIDADES = { '&quot;': '"', '&#39;': "'", '&apos;': "'", '&lt;': '<', '&gt;': '>', '&nbsp;': ' ', '&amp;': '&' };
const limpiar = (t) =>
  String(t ?? '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&(?:quot|#39|apos|lt|gt|nbsp|amp);/g, (m) => ENTIDADES[m]);

const config = $('Configuración').item.json;
const resumen = $('Resumir con Gemini').item.json.text ?? '';
return {
  json: {
    original: config.texto,
    resumen: resumen.trim(),
    idioma: config.idioma,
    codigo_idioma: config.codigo_idioma,
    traduccion: limpiar($json.translatedText).trim(),
    idioma_detectado: $json.detectedSourceLanguage ?? '',
  },
};
